    19→            compatible = "arm,cortex-m33";
    20→            reg = <0>;
    21→            clock-frequency = <120000000>;  /* 来源: bk_idk CONFIG_DCO_FREQ */
    22→        };
    23→    };
    24→
    25→    /*
    26→     * ★★★ 内存映射（来源: bk_idk/include/soc/bk7258/reg_base.h）★★★
    27→     *
    28→     * 注意！BK7258 的真实地址：
    29→     *   - Flash 在 0x02000000（不是 0x0！0x0 是 ITCM）
    30→     *   - SRAM 在 0x28000000（不是 0x20000000！0x20000000 是 DTCM）
    31→     *
    32→     * hello_world 先用 SRAM0+SRAM1（连续 128 KB），跑得稳后再扩到 640 KB
    33→     */
    34→
    35→    /* 片内 Flash: Tuya normal bootloader 的 app 虚拟地址
    36→     * Beken code flash 每 32 字节数据追加 2 字节 CRC，
    37→     * app virtual 0x02010000 对应烧录 physical offset 0x11000。 */
    38→    flash0: flash@2010000 {
    39→        compatible = "soc-nv-flash";
    40→        reg = <0x02010000 0x003F0000>;    /* ~4 MB - 64K virtual app offset */
    41→    };
    42→
    43→    /* SRAM0+SRAM1 连续区段: 128 KB @ 0x28000000
    44→     * 来源: SOC_SRAM0_DATA_BASE(64K) + SOC_SRAM1_DATA_BASE(64K)
    45→     * 这两块在物理地址上紧邻，可以合并成一块。 */
    46→    sram0: memory@28000000 {
    47→        compatible = "mmio-sram";
    48→        reg = <0x28000000 0x00020000>;    /* 128 KB */
    49→    };
    50→
    51→    /* 时钟树（占位，等驱动完善后扩展）
    52→     * 来源: bk_idk CONFIG_XTAL_FREQ=26000000, CONFIG_DCO_FREQ=120000000 */
    53→    sysclk: clock-system {
    54→        compatible = "fixed-clock";
    55→        clock-frequency = <120000000>;
    56→        #clock-cells = <0>;
    57→    };
    58→};
    59→
    60→/* NVIC：3 位优先级（8 个优先级等级）
    61→ * 来源: bk_idk interrupts.c 用 PRI_GOURP_BITS_7_5，对应 3 位 preemption + 1 位 subpriority，
    62→ *       Zephyr 不使用分组，所以取 preemption 部分的位数 = 3。
    63→ *       (后续实际烧写验证时再校准) */
    64→&nvic {
    65→    arm,num-irq-priority-bits = <3>;
    66→};

