   135→static int read_uart(const struct device *uart, uint8_t *buf,
   136→		     unsigned int size)
   137→{
   138→	int rx;
   139→
   140→	rx = uart_fifo_read(uart, buf, size);
   141→	if (rx < 0) {
   142→		/* Overrun issue. Stop the UART */
   143→		uart_irq_rx_disable(uart);
   144→
   145→		return -EIO;
   146→	}
   147→
   148→	return rx;
   149→}
