   171→static void insert_char(char *pos, char c, uint8_t end)
   172→{
   173→	char tmp;
   174→
   175→	/* Echo back to console */
   176→	uart_poll_out(uart_console_dev, c);
   177→
   178→	if (end == 0U) {
   179→		*pos = c;
   180→		return;
   181→	}
   182→
   183→	tmp = *pos;
   184→	*(pos++) = c;
   185→
   186→	cursor_save();
   187→
   188→	while (end-- > 0) {
   189→		uart_poll_out(uart_console_dev, tmp);
   190→		c = *pos;
   191→		*(pos++) = tmp;
   192→		tmp = c;
   193→	}
   194→
   195→	/* Move cursor back to right place */
   196→	cursor_restore();
   197→}
   198→
   199→static void del_char(char *pos, uint8_t end)
   200→{
   201→	uart_poll_out(uart_console_dev, '\b');
   202→
   203→	if (end == 0U) {
   204→		uart_poll_out(uart_console_dev, ' ');
   205→		uart_poll_out(uart_console_dev, '\b');
   206→		return;
   207→	}
   208→
   209→	cursor_save();
   210→
   211→	while (end-- > 0) {
   212→		*pos = *(pos + 1);
   213→		uart_poll_out(uart_console_dev, *(pos++));
   214→	}
   215→
   216→	uart_poll_out(uart_console_dev, ' ');
   217→
   218→	/* Move cursor back to right place */
   219→	cursor_restore();
   220→}
